def f1(x, y):
    return (x + y) * (x + y + 1) // 2 + y

def f2(x, y):
    return (x + y) * (x + y + 1) // 2 + x

def count_odd(f, limit):
    count = 0
    for x in range(limit):
        for y in range(limit):
            if f(x, y) % 2 == 1:
                count += 1
    return count

